-- Data: generated by scripts/impact-data.mjs (2026-11-01)





-- Link the charities to the Organizations donors give to. Reviewed by hand: same abbreviation,
-- except SS = Sightsavers ("Sight"). Matched by abbreviation because Organization IDs differ
-- between production and dev data; an organization that doesn't exist leaves the charity
-- unlinked. prisma/devdata/impact.ts holds the same list for the dev seed.
UPDATE `Impact_charities` c
  JOIN (
    SELECT 'AMF' AS charity, 'AMF' AS org
    UNION ALL SELECT 'SCI', 'SCI'
    UNION ALL SELECT 'HKI', 'HKI'
    UNION ALL SELECT 'NI', 'NI'
    UNION ALL SELECT 'END', 'End'
    UNION ALL SELECT 'DTW', 'DtW'
    UNION ALL SELECT 'SS', 'Sight'
    UNION ALL SELECT 'GD', 'GD'
    UNION ALL SELECT 'UBI', 'UBI'
    UNION ALL SELECT 'MC', 'MC'
    UNION ALL SELECT 'NLS', 'NLS'
    UNION ALL SELECT 'PHC', 'PHC'
    UNION ALL SELECT 'GDZF', 'GDZF'
    UNION ALL SELECT 'GDCSF', 'GDCSF'
    UNION ALL SELECT 'AGF', 'AGF'
  ) m ON m.charity = c.abbreviation
  JOIN `Organizations` o ON o.abbriv = m.org
  SET c.Organization_ID = o.ID;
